proof fn log_range_no_node_id_matches_empty<DT: Dispatch>(
    log: Map<LogIdx, LogEntry<DT>>,
    start: LogIdx,
    end: LogIdx,
    node_id: NodeId,
)
    requires
        start <= end,
        LogContainsEntriesUpToHere(log, end),
        LogRangeNoNodeId(log, start, end, node_id),
    ensures
        LogRangeMatchesQueue(
            Seq::<ReqId>::empty(), log, 0, start, end, node_id,
            Map::<ReqId, UpdateState<DT>>::empty()
        ),
    decreases end - start,
{
    if start < end {
        assert(log.contains_key(start));
        assert(log.index(start).node_id != node_id);
        log_range_no_node_id_matches_empty(log, start + 1, end, node_id);
    }
}

